def build_contexts(traces, K):
    """Contexts in partition order: trace array order, increasing end time."""
    out = []
    for tid, src, rows in traces:
        n = len(rows)
        if n < K:
            continue
        srt = sorted(rows, key=lambda r: r[0])
        vals = [r[1] for r in srt]
        ts = [r[0] for r in srt]
        for i in range(n - K + 1):
            out.append((tid, ts[i + K - 1], vals[i:i + K], src))
    return out


def parse_request(req):
    """Validate everything; return the pieces needed for computation."""
    if not is_dict(req) or set(req) != TOPKEYS:
        raise SchemaErr('top')
    if not is_int(req['version']) or req['version'] != 1:
        raise SchemaErr('version')
    K = req['window']
    if not is_int(K) or not 1 <= K <= 8:
        raise SchemaErr('window')
    pol = req['policy']
    if not is_dict(pol) or set(pol) != {'max_width', 'min_support',
                                        'min_witness'}:
        raise SchemaErr('policy')
    B = pol['max_width']
    S = pol['min_support']
    W = pol['min_witness']
